add_filter( 'woocommerce_product_add_to_cart_text', 'perfectpixel_add_to_cart_symbol', 90 );

function perfectpixel_add_to_cart_symbol( $text ) {
	$symbol = trim( '{{atc_symbol}}' );
	if ( '' === $symbol ) {
		return $text;
	}
	return 'before' === '{{atc_symbol_position}}' ? $symbol . ' ' . $text : $text . ' ' . $symbol;
}
